# STEP 3: IMPLEMENT THE LLM FUNCTION
def llm_model(system_msg, prompt_txt):
    model_id = "ibm/granite-4-h-small"
    project_id = "skills-network"
    credentials = Credentials(url = "https://us-south.ml.cloud.ibm.com")

    ### 3.1: Define the model by ModelInference
    model = ModelInference(model_id = model_id,
                           credentials = credentials,
                           project_id = project_id)

    ### 3.2: Define the messages
    messages = [{"role": "system", "content": system_msg},
                {"role": "user", "content": prompt_txt}]

    ### 3.3: Get the final response output and return it
    response = model.chat(messages = messages)
    return response["choices"][0]["message"]["content"]

# STEP 4: TESTING THE LLM MODEL
import time

def safe_llm_call(system_msg, prompt_txt, retries = 3):
    for i in range(retries):
        try:
            return llm_model(system_msg, prompt_txt)
        except Exception:
            time.sleep(2)
    return "Failed after retries"

