from pydantic import BaseModel, Field, ValidationError
from typing import List, Optional

### 6.1: Define the schema
class Restaurant(BaseModel):
    name: str
    location: str
    type: str
    food_style: str
    rating: Optional[float] = None
    price_range: Optional[int] = None
    signatures: List[str] = Field(default_factory = list)
    vibe: Optional[str] = None
    environment: str
    shortcomings: List[str] = Field(default_factory = list)

### 6.2: Use the validation method to validate the test_response from the unit test
try:
    restaurant_data = Restaurant.model_validate_json(test_response)
    print(f"Success! Validated: {restaurant_data.name}")
except ValidationError as e:
    print(f"Validation failed: {e.json()}")

# STEP 7: STRUCTURE THE RESTAURANT DATA

# Define prompts to have an LLM that auto repairs outputs to JSON format
def JSON_auto_repair_prompts(candidate_json_output, error_message):

    auto_repair_system_msg = """You are a strict JSON correction engine.
                                Your only task is to fix invalid or malformed JSON so that it becomes valid, schema-compliant JSON.
            
                                Rules:
                                - Output ONLY valid JSON. No explanations, no markdown, no extra text.
                                - Preserve as much of the original content as possible.
                                - Do NOT invent new information unless required to fix structural/schema issues.
                                - Follow the schema implied by the validation error message.
                                - Fix common issues such as:
                                  - Missing commas, brackets, or quotes
                                  - Incorrect data types (e.g., string vs number)
                                  - Extra trailing commas
                                  - Incorrect nesting or structure
                                - Ensure final output is parseable by a standard JSON parser.
                                """

    auto_repair_prompt = f"""You are given:
                             1. A candidate JSON output that failed validation: {candidate_json_output}
                             2. The validation error message: {error_message}

                             Task:
                             - Carefully analyze the error message to identify what is wrong.
                             - Repair the JSON so that it fully conforms to the required format.
                             - Keep all valid data unchanged unless it violates the schema.
                             - Return ONLY the corrected JSON output.
                            
                             Do NOT include any commentary or explanation.
                             Return only valid JSON."""

    return auto_repair_system_msg, auto_repair_prompt

# Run the for loop to go over all the restaurant data in the list
import json
from pydantic import ValidationError

structured_restaurant_lists = []

for i, restaurant_paragraph in enumerate(restaurant_list):
    ### 7.1: Initial LLM generation (use your prompt function)
    system_msg, user_prompt = restaurant_data_structure_prompt_generation(restaurant_paragraph)
    output = llm_model(system_msg = system_msg, prompt_txt = user_prompt)
  
    ### 7.2: Validation + Auto-repair loop (Pydantic-based)
    max_retries = 3
    retry = 0
    while retry < max_retries:
        try:
            restaurant_obj = Restaurant.model_validate_json(output)
            break
        except ValidationError as e:
            error_message = e.json()
            repair_system_msg, repair_prompt = JSON_auto_repair_prompts(candidate_json_output = output, error_message = error_message)
            output = llm_model(system_msg = repair_system_msg, prompt_txt = repair_prompt)
            retry += 1

    ### 7.3: Append final structured result
    try:
        structured_restaurant_lists.append(Restaurant.model_validate_json(output).model_dump_json())
    except ValidationError:
        structured_restaurant_lists.append({"error": "unparseable_json", "raw_output": output})

    # Tracking Progress (Every 20 restaurants)
    if (i + 1) % 20 == 0:
        print(f"{i+1} out of {len(restaurant_list)} is done")

print("ALL DONE!!")

